+    summary: '轉強', importance, freshness: 'previous_trading_day', published_at: '2026-09-22',
+    raw_reference: `sector_rotation_scores:${title}@2026-09-22`, quality_status: 'context',
+  }));
+  return [...market, ...news, ...sectors];
+}
